// HasResource applies the HasEdge predicate on the "resource" edge.
func HasResource() predicate.EnterpriseResourceAddress {
	return predicate.EnterpriseResourceAddress(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, ResourceTable, ResourceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasResourceWith applies the HasEdge predicate on the "resource" edge with a given conditions (other predicates).
func HasResourceWith(preds ...predicate.EnterpriseResource) predicate.EnterpriseResourceAddress {
	return predicate.EnterpriseResourceAddress(func(s *sql.Selector) {
		step := newResourceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EnterpriseResourceAddress) predicate.EnterpriseResourceAddress {
	return predicate.EnterpriseResourceAddress(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EnterpriseResourceAddress) predicate.EnterpriseResourceAddress {
	return predicate.EnterpriseResourceAddress(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EnterpriseResourceAddress) predicate.EnterpriseResourceAddress {
	return predicate.EnterpriseResourceAddress(sql.NotPredicates(p))
}
